{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policies are attached only to groups or roles",
      "resource": "aws_iam_user_policy_attachment.privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching IAM policies directly to users can lead to excessive privileges and increased management complexity."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc19-UpdateExistingGlueDevEndpoint-group" {
  name = "privesc19-UpdateExistingGlueDevEndpoint-group"
}

resource "aws_iam_group_membership" "privesc19-UpdateExistingGlueDevEndpoint-membership" {
  name  = "privesc19-UpdateExistingGlueDevEndpoint-membership"
  users = [aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name]
  group = aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name
}

resource "aws_iam_policy_attachment" "privesc19-UpdateExistingGlueDevEndpoint-attach-policy" {
  name       = "privesc19-UpdateExistingGlueDevEndpoint-attach-policy"
  groups     = [aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name]
  policy_arn = aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint.arn
}",
  "fix_summary": "Replaced aws_iam_user_policy_attachment with aws_iam_group and aws_iam_group_membership to attach the policy to a group instead of a user, reducing access management complexity."
}
